"use client";
/* eslint-disable @next/next/no-html-link-for-pages */

import { useMemo, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, ArrowRight, Bell, Check, CheckCircle2, Download, FileText, Filter, KeyRound, LoaderCircle, Merge, Play, Plus, RefreshCcw, Send, ShieldCheck, UploadCloud, WandSparkles, XCircle } from "lucide-react";
import { client, type IntakeJob } from "@/lib/api";
import { Topbar } from "./topbar";

function tone(value: string) { const text = value.toLowerCase(); if (/(approved|published|completed|ready|healthy|resolved|delivered)/.test(text)) return "badge-green"; if (/(review|pending|processing|received|warning|needs)/.test(text)) return "badge-amber"; if (/(blocked|failed|rejected|error)/.test(text)) return "badge-coral"; return "badge-blue"; }
function Badge({ children }: { children: React.ReactNode }) { return <span className={`badge ${tone(String(children))}`}>{children}</span>; }
function Empty({ title, copy }: { title: string; copy: string }) { return <div className="empty-state"><div className="empty-mark">CF</div><b>{title}</b><p>{copy}</p></div>; }
function Loading({ label = "Loading workspace data…" }: { label?: string }) { return <div className="loading"><LoaderCircle className="spin" size={18} /> {label}</div>; }
function ErrorState({ message }: { message: string }) { return <div className="error-state"><AlertTriangle size={18} /><div><b>Live workspace data is unavailable</b><p>{message}</p></div></div>; }
function Kpi({ label, value, note }: { label: string; value: string | number; note: string }) { return <article className="card kpi"><span className="label">{label}</span><span className="num">{value}</span><span className="trend">{note}</span></article>; }
function Panel({ title, children, action }: { title: string; children: React.ReactNode; action?: React.ReactNode }) { return <section className="card card-pad"><div className="section-row"><div className="section-title">{title}</div>{action}</div>{children}</section>; }
function ApiToast({ text }: { text?: string }) { return text ? <div className="toast">{text}</div> : null; }

function Dashboard() {
  const { data, isLoading, error } = useQuery({ queryKey: ["overview"], queryFn: client.overview });
  if (isLoading) return <><Topbar title="Operations overview" /><Loading /></>;
  if (error || !data) return <><Topbar title="Operations overview" /><ErrorState message={(error as Error)?.message || "Unable to load overview."} /></>;
  const metric = data.metrics;
  return <><Topbar title="Operations overview" action={<a className="btn btn-cobalt" href="/workspace/source-intake"><UploadCloud size={16} /> Upload supplier file</a>} /><div className="workspace-grid grid-kpi"><Kpi label="Products extracted" value={metric.products_extracted} note="Live API count" /><Kpi label="Awaiting review" value={metric.awaiting_review} note="Priority queues active" /><Kpi label="Publish-ready" value={metric.publish_ready} note="Approval-gated" /><Kpi label="Catalog quality" value={`${metric.catalog_quality_score}%`} note="Rules-based synthetic score" /></div><div className="workspace-grid grid-2" style={{ marginTop: 16 }}><Panel title="Operational briefing"><p className="summary-copy">{data.summary}</p><div className="callout"><ShieldCheck size={17} /><span>{data.limitations}</span></div><div className="metric-bar-list">{data.confidence_distribution.map((item) => <div key={item.band}><div className="section-row" style={{ marginBottom: 6 }}><span className="small">{item.band}</span><b className="small">{item.count}</b></div><div className="progress"><span style={{ width: `${Math.min(100, item.count / Math.max(...data.confidence_distribution.map((v) => v.count)) * 100)}%` }} /></div></div>)}</div></Panel><Panel title="Priority review queue" action={<a href="/workspace/review" className="btn btn-secondary compact">Open queue <ArrowRight size={14} /></a>}>{data.recent_activity.map((job) => <div className="activity-row" key={job.id}><div><b>{job.filename}</b><span>{job.vendor} · {job.product_count} records · {Math.round(job.confidence * 100)}% confidence</span></div><Badge>{job.status}</Badge></div>)}</Panel></div><div className="workspace-grid grid-3" style={{ marginTop: 16 }}><Panel title="Pipeline status"><p className="small muted">Live durable jobs are tracked with retry metadata and linked audit events.</p><a href="/workspace/pipeline" className="text-link">Open Operations Pipeline Center →</a></Panel><Panel title="Destination health"><p className="small muted">Mock destinations are clearly labeled. A product is publishable only after validation, approval, and channel-readiness gates pass.</p><a href="/workspace/publish" className="text-link">Open Publish Center →</a></Panel><Panel title="Data lineage"><p className="small muted">Field values retain source text, row/page evidence, normalization history, reviewer overrides, and destination mapping.</p><a href="/workspace/lineage" className="text-link">Trace a product →</a></Panel></div></>;
}

function Intake() {
  const queryClient = useQueryClient(); const [selected, setSelected] = useState<IntakeJob | undefined>(); const [toast, setToast] = useState("");
  const { data, isLoading, error } = useQuery({ queryKey: ["intake"], queryFn: client.intakeJobs });
  const process = useMutation({ mutationFn: (id: string) => client.processJob(id), onSuccess: (result: { status: string; product_count: number }) => { setToast(`Deterministic extraction completed: ${result.product_count} candidates routed to ${result.status}.`); queryClient.invalidateQueries({ queryKey: ["intake"] }); queryClient.invalidateQueries({ queryKey: ["products"] }); }, onError: (e: Error) => setToast(e.message) });
  const jobs = data?.items || []; const active = selected || jobs[0];
  return <><Topbar title="Intake inbox" action={<a href="/workspace/source-intake" className="btn btn-cobalt"><UploadCloud size={16} /> Upload files</a>} /><div className="dropzone"><div><b>Media and Source Intake Center</b><p>CSV, XLSX, JSON, PDF, images, and safe archive boundary. Every upload is checked for extension, MIME signature, size, and checksum.</p></div><a className="btn btn-secondary" href="/workspace/source-intake">Open intake form <ArrowRight size={15} /></a></div>{isLoading ? <Loading /> : error ? <ErrorState message={(error as Error).message} /> : <div className="workspace-grid grid-2"><Panel title={`Incoming jobs · ${jobs.length}`}><div className="table-wrap"><table><thead><tr><th>Source</th><th>Vendor</th><th>Status</th><th>Confidence</th><th>Records</th></tr></thead><tbody>{jobs.map((job) => <tr key={job.id} className={active?.id === job.id ? "selected-row" : ""} onClick={() => setSelected(job)}><td><b>{job.filename}</b><div className="small muted">{job.source_type}</div></td><td>{job.vendor}</td><td><Badge>{job.status}</Badge></td><td>{Math.round(job.confidence * 100)}%</td><td>{job.product_count}</td></tr>)}</tbody></table></div></Panel><Panel title="Job control" action={active && <Badge>{active.status}</Badge>}>{active ? <><div className="detail-stack"><div><span>Vendor</span><b>{active.vendor}</b></div><div><span>Validation findings</span><b>{active.validation_failures}</b></div><div><span>Source quality</span><b>{Math.round((active.source_quality_score || 0) * 100)}%</b></div><div><span>Processing mode</span><b>{active.mode || "Extract and review"}</b></div></div><div className="divider" /><p className="small muted">The extraction action calls the FastAPI deterministic parser and persists candidates, evidence, validations, channel readiness, review tasks, and job history.</p><button className="btn btn-cobalt" disabled={process.isPending} onClick={() => process.mutate(active.id)}><Play size={16} /> {process.isPending ? "Processing…" : "Run deterministic pipeline"}</button>{active.document_id && <a className="btn btn-secondary" href={`/workspace/documents?document=${active.document_id}`}>Inspect source evidence</a>}</> : <Empty title="No intake jobs" copy="Upload a source file to start an import." />}</Panel></div>}<ApiToast text={toast} /></>;
}

function SourceIntake() {
  const queryClient = useQueryClient(); const { data: vendors } = useQuery({ queryKey: ["vendors"], queryFn: client.vendors }); const [vendorId, setVendorId] = useState(""); const [file, setFile] = useState<File | null>(null); const [mode, setMode] = useState("Extract and review"); const [toast, setToast] = useState("");
  const upload = useMutation({ mutationFn: () => client.upload(vendorId || vendors?.items[0]?.id || "", file!, mode), onSuccess: (result: { job_id: string; source_type: string; duplicate_hint: boolean }) => { setToast(`Upload validated as ${result.source_type}${result.duplicate_hint ? "; matching checksum exists in this workspace" : ""}.`); queryClient.invalidateQueries({ queryKey: ["intake"] }); }, onError: (e: Error) => setToast(e.message) });
  return <><Topbar title="Media and Source Intake Center" /><div className="workspace-grid grid-2"><Panel title="Safe local import"><div className="form-grid"><label>Vendor<select value={vendorId} onChange={(e) => setVendorId(e.target.value)}>{vendors?.items.map((vendor) => <option key={vendor.id} value={vendor.id}>{vendor.name}</option>)}</select></label><label>Import mode<select value={mode} onChange={(e) => setMode(e.target.value)}><option>Draft</option><option>Validate only</option><option>Extract and review</option><option>Extract and publish after approval</option></select></label></div><label className="file-picker"><UploadCloud size={20} /><span>{file?.name || "Choose CSV, XLSX, JSON, PDF, TXT, or image"}</span><input type="file" accept=".csv,.xlsx,.xls,.json,.pdf,.txt,.png,.jpg,.jpeg,.webp,.svg" onChange={(e) => setFile(e.target.files?.[0] || null)} /></label><div className="callout"><ShieldCheck size={16} /><span>ZIP intake is modeled as a secure archive-scanning boundary and intentionally disabled in local demo mode. Uploaded files are treated as user data, never synthetic demo data.</span></div><button className="btn btn-cobalt" disabled={!file || upload.isPending || !vendors?.items.length} onClick={() => upload.mutate()}><UploadCloud size={16} /> {upload.isPending ? "Validating…" : "Validate and create intake job"}</button></Panel><Panel title="What local mode implements"><ul className="feature-list"><li><Check size={15} /> Extension, signature/MIME, size, and checksum validation</li><li><Check size={15} /> Column preview and suggested mapping for CSV/XLSX/JSON</li><li><Check size={15} /> PyMuPDF text extraction boundary for PDFs with deterministic fallback</li><li><Check size={15} /> Immutable source metadata and import audit events</li><li><Check size={15} /> Inline deterministic pipeline; no OCR, LLM, cloud, email, or connector keys</li></ul><p className="small muted">Provider adapters and public vendor portal delivery remain explicitly marked as optional production boundaries.</p></Panel></div><ApiToast text={toast} /></>;
}

function Documents() {
  const [selectedId, setSelectedId] = useState<string | undefined>(); const { data: docs, isLoading, error } = useQuery({ queryKey: ["documents"], queryFn: client.documents }); const active = selectedId || docs?.items[0]?.id; const { data: document } = useQuery({ queryKey: ["document", active], queryFn: () => client.document(active!), enabled: Boolean(active) }); const { data: evidence } = useQuery({ queryKey: ["evidence", active], queryFn: () => client.documentEvidence(active!), enabled: Boolean(active) }); const [fieldId, setFieldId] = useState<string | undefined>(); const selectedField = evidence?.items.find((item) => item.id === fieldId) || evidence?.items[0];
  return <><Topbar title="Document intelligence" />{isLoading ? <Loading /> : error ? <ErrorState message={(error as Error).message} /> : <div className="workspace-split card"><section className="doc-preview"><div className="section-row"><div><b>{document?.filename || "Source document"}</b><div className="small muted">{document?.source_type} · {document?.page_count} page(s)</div></div><Badge>{document?.retention_state || "Active"}</Badge></div><div className="doc-paper"><div className="doc-label">SYNTHETIC / USER UPLOAD PREVIEW</div><h3>{document?.filename}</h3><p>Source-backed document metadata. In local demo mode, PDF text and spreadsheet rows are represented through field evidence; a production PDF canvas can be connected without changing lineage identifiers.</p>{(document?.pages || []).map((page) => <div className="ocr-box" key={page.id} style={{ left: 34, top: 146 + page.page_number * 44, width: "78%", height: 34 }}><span>Page {page.page_number}{page.sheet_name ? ` · ${page.sheet_name}` : ""}</span></div>)}</div><div className="document-list">{docs?.items.slice(0, 8).map((item) => <button key={item.id} className={`doc-chip ${item.id === active ? "active" : ""}`} onClick={() => { setSelectedId(item.id); setFieldId(undefined); }}>{item.filename}</button>)}</div></section><section className="center-records"><div className="section-row"><div><div className="section-title">Extracted fields</div><div className="small muted">Click a field to inspect source and transformation lineage.</div></div><Badge>{evidence?.items.length || 0} evidence records</Badge></div>{evidence?.items.slice(0, 18).map((field) => <button key={field.id} className={`record-card ${field.id === selectedField?.id ? "active" : ""}`} onClick={() => setFieldId(field.id)}><div className="section-row" style={{ marginBottom: 3 }}><b>{field.field}</b><span className="small">{Math.round(field.confidence * 100)}%</span></div><div className="value">{field.value}</div><div className="small muted">{field.method} · {field.validation_status}</div></button>)}</section><section className="evidence-panel"><div className="section-title">Field evidence</div><p className="small muted">This panel is backed by persistent extracted-field and source-document records.</p>{selectedField ? <><div className="evidence-field"><span className="key">Original source value</span><div className="value">{selectedField.original_value}</div></div><div className="evidence-field"><span className="key">Normalized value</span><div className="value">{selectedField.normalized_value}</div></div><div className="evidence-field"><span className="key">Source pointer</span><div className="small">{String(selectedField.evidence.source_text || "—")}</div><div className="small muted">page {String(selectedField.evidence.page || "—")} · row {String(selectedField.evidence.row || "—")}</div></div><div className="evidence-field"><span className="key">Transformation history</span><div className="small">{JSON.stringify(selectedField.transformation_history)}</div></div><div className="evidence-field"><span className="key">Destination mapping</span><div className="small">{JSON.stringify(selectedField.destination_mapping)}</div></div><div className="callout"><ShieldCheck size={15} /><span>Reviewer overrides are recorded against the field, not silently written over its original evidence.</span></div></> : <Empty title="No evidence fields" copy="Run the deterministic parser on an intake job." />}</section></div>}</>;
}

function ProductMaster() {
  const [selectedId, setSelectedId] = useState<string | undefined>(); const { data: products, isLoading } = useQuery({ queryKey: ["products", "master"], queryFn: () => client.products("limit=40") }); const active = selectedId || products?.items[0]?.id; const { data: product, error } = useQuery({ queryKey: ["product", active], queryFn: () => client.product(active!), enabled: Boolean(active) });
  return <><Topbar title="Product Master workspace" action={<a className="btn btn-secondary" href="/workspace/catalog">Open catalog grid</a>} />{isLoading ? <Loading /> : error ? <ErrorState message={(error as Error).message} /> : <div className="workspace-grid product-master-layout"><Panel title="Product master records"><div className="master-list">{products?.items.map((item) => <button key={item.id} className={`product-row ${item.id === active ? "active" : ""}`} onClick={() => setSelectedId(item.id)}><img src={item.image_url} alt="" /><div><b>{item.title}</b><span>{item.sku || "Missing SKU"} · {item.brand}</span></div><Badge>{item.status}</Badge></button>)}</div></Panel><section className="card card-pad">{product ? <><div className="section-row"><div><div className="eyebrow">Product master</div><h2 className="h2" style={{ fontSize: 28, marginTop: 5 }}>{product.title}</h2><span className="small muted">{product.sku || "No SKU"} · versioned, source-linked record</span></div><Badge>{product.status}</Badge></div><div className="review-grid" style={{ marginTop: 16 }}><div className="gallery-main"><img src={product.image_url} alt={product.title} /></div><div><div className="score-grid"><div><span>Completeness</span><b>{product.completeness_score}%</b></div><div><span>Quality</span><b>{product.quality_score}%</b></div><div><span>Confidence</span><b>{Math.round(product.confidence * 100)}%</b></div><div><span>Inventory</span><b>{product.inventory}</b></div></div><div className="attribute-list" style={{ marginTop: 14 }}>{Object.entries(product.attributes).map(([key, value]) => <div className="attr" key={key}><span className="key">{key}</span><b>{value || "—"}</b></div>)}</div></div></div><div className="divider" /><div className="section-title">Channel readiness</div><div className="readiness-grid">{product.channel_readiness?.map((item) => <div className="readiness-card" key={item.id}><b>{item.channel}</b><Badge>{item.status}</Badge><span>{item.blockers.items?.length ? item.blockers.items.join(", ") : "All configured checks pass"}</span></div>)}</div><div className="divider" /><div className="section-title">Version timeline</div>{product.versions?.slice(0, 4).map((version) => <div className="timeline-row" key={`${version.version}-${version.at}`}><b>v{version.version}</b><span>{version.summary}</span><small>{version.actor}</small></div>)}</> : <Empty title="Select a product" copy="Choose a source-linked record from the Product Master list." />}</section></div>}</>;
}

function Review() {
  const queryClient = useQueryClient(); const { data, isLoading, error } = useQuery({ queryKey: ["review"], queryFn: client.reviewTasks }); const [selected, setSelected] = useState<string | undefined>(); const [sku, setSku] = useState(""); const [weight, setWeight] = useState(""); const [note, setNote] = useState(""); const [toast, setToast] = useState(""); const task = data?.items.find((item) => item.id === selected) || data?.items.find((item) => item.status === "Open") || data?.items[0]; const product = task?.product;
  const refresh = () => { queryClient.invalidateQueries({ queryKey: ["review"] }); queryClient.invalidateQueries({ queryKey: ["products"] }); queryClient.invalidateQueries({ queryKey: ["overview"] }); };
  const correct = useMutation({ mutationFn: () => client.updateProduct(product!.id, { sku: sku || product!.sku, attributes: { ...product!.attributes, weight: weight || product!.attributes.weight || "" } }), onSuccess: () => { setToast("Reviewer correction persisted with field-level override history."); refresh(); }, onError: (e: Error) => setToast(e.message) });
  const approve = useMutation({ mutationFn: () => client.approveProduct(product!.id, note), onSuccess: () => { setToast("Product approval persisted; publish readiness was recalculated."); refresh(); }, onError: (e: Error) => setToast(e.message) });
  const clarify = useMutation({ mutationFn: () => client.requestClarification(product!.id), onSuccess: () => { setToast("Vendor clarification task created in the active workspace."); refresh(); }, onError: (e: Error) => setToast(e.message) });
  return <><Topbar title="Product review workspace" />{isLoading ? <Loading /> : error ? <ErrorState message={(error as Error).message} /> : !task || !product ? <Empty title="No review tasks" copy="All review queues are clear in this workspace." /> : <div className="review-shell"><aside className="review-queue"><div className="section-row"><b>High-throughput queue</b><span className="small muted">{data?.items.filter((item) => item.status === "Open").length} open</span></div>{data?.items.slice(0, 18).map((item) => <button key={item.id} className={`queue-item ${item.id === task.id ? "active" : ""}`} onClick={() => { setSelected(item.id); setSku(item.product.sku); setWeight(item.product.attributes.weight || ""); }}><Badge>{item.priority}</Badge><b>{item.product.title}</b><span>{item.reason} · {item.assignee}</span></button>)}</aside><section className="review-body"><div className="section-row"><div><div className="eyebrow">{task.queue}</div><h2 className="h2" style={{ fontSize: 29, marginTop: 5 }}>{product.title}</h2><div className="small muted">{product.brand} · {product.category} · source-linked candidate</div></div><Badge>{product.status}</Badge></div><div className="review-grid" style={{ marginTop: 18 }}><div><div className="gallery-main"><img src={product.image_url} alt={product.title} /></div><div className="source-card"><b>Required-field checklist</b>{["Title", "SKU", "Price", "Shipping weight", "Category"].map((label) => <div key={label}><span>{product.sku || label !== "SKU" ? "✓" : "!"}</span>{label}</div>)}</div></div><div className="review-fields"><label>SKU<input value={sku || product.sku} onChange={(e) => setSku(e.target.value)} placeholder="Set a normalized SKU" /></label><label>Shipping weight<input value={weight || product.attributes.weight || ""} onChange={(e) => setWeight(e.target.value)} placeholder="e.g. 0.62 kg" /></label><label>Reviewer note<textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Optional decision note; @mention is stored as a collaboration hint." /></label><div className="validation-list">{product.validations.map((validation) => <div key={validation.id} className={validation.blocking && validation.state === "open" ? "validation-block" : "validation-warning"}><b>{validation.rule}</b><span>{validation.message}</span><small>{validation.remediation}</small></div>)}</div></div></div><div className="review-actions"><button className="btn btn-secondary" onClick={() => correct.mutate()} disabled={correct.isPending}><CheckCircle2 size={16} /> Save correction <kbd>⌘S</kbd></button><button className="btn btn-cobalt" onClick={() => approve.mutate()} disabled={approve.isPending}><Check size={16} /> Approve product <kbd>A</kbd></button><button className="btn btn-secondary" onClick={() => clarify.mutate()} disabled={clarify.isPending}><Send size={16} /> Request vendor clarification <kbd>F</kbd></button></div><div className="callout"><ShieldCheck size={16} /><span>Approve is intentionally blocked until configured validation, duplicate, and destination-readiness gates pass. Corrections preserve original values and create a versioned audit record.</span></div></section></div>}<ApiToast text={toast} /></>;
}

function Catalog() { const { data, isLoading, error } = useQuery({ queryKey: ["products", "catalog"], queryFn: () => client.products("limit=80") }); return <><Topbar title="Catalog spreadsheet workspace" action={<a className="btn btn-secondary" href="/workspace/product-master">Product Master</a>} />{isLoading ? <Loading /> : error ? <ErrorState message={(error as Error).message} /> : <Panel title="Spreadsheet-style catalog table" action={<span className="small muted">Inline edits create product versions and audit events.</span>}><div className="table-wrap catalog-table"><table><thead><tr><th>Product</th><th>SKU</th><th>Brand</th><th>Category</th><th>Price</th><th>Inventory</th><th>Completeness</th><th>Validation</th><th>Publish state</th></tr></thead><tbody>{data?.items.map((item) => <tr key={item.id}><td><div className="product-mini"><img src={item.image_url} alt="" /><div><b>{item.title}</b><div className="small muted">{item.barcode}</div></div></div></td><td><code>{item.sku || "MISSING"}</code></td><td>{item.brand}</td><td>{item.category}</td><td>${item.price.toFixed(2)}</td><td>{item.inventory}</td><td>{item.completeness_score}%</td><td><Badge>{item.validations.some((v) => v.blocking && v.state === "open") ? "Blocked" : "Healthy"}</Badge></td><td><Badge>{item.status}</Badge></td></tr>)}</tbody></table></div><div className="callout"><Filter size={16} /><span>Column management, saved views, bulk editing and exports are exposed by the API contract. This dense desktop grid intentionally shifts to summary layouts on smaller screens.</span></div></Panel>}</> }

function Duplicates() {
  const queryClient = useQueryClient(); const { data, isLoading, error } = useQuery({ queryKey: ["duplicates"], queryFn: client.duplicates }); const [selected, setSelected] = useState<string | undefined>(); const [toast, setToast] = useState(""); const groupId = selected || data?.items.find((item) => item.status === "Candidate")?.id || data?.items[0]?.id; const { data: detail } = useQuery({ queryKey: ["duplicate", groupId], queryFn: () => client.duplicate(groupId!), enabled: Boolean(groupId) }); const act = useMutation({ mutationFn: ({ decision, confirm }: { decision: "merge" | "separate"; confirm?: boolean }) => decision === "merge" ? client.mergeDuplicate(groupId!, { rationale: "Reviewed source evidence and field differences in Phase 2 demo.", canonical_product_id: detail?.left?.id, confirm_second_review: confirm }) : client.separateDuplicate(groupId!, "Reviewed source evidence; retain distinct records."), onSuccess: (result: { status: string; message?: string }) => { setToast(result.message || `Duplicate decision saved: ${result.status}.`); queryClient.invalidateQueries({ queryKey: ["duplicates"] }); queryClient.invalidateQueries({ queryKey: ["audit"] }); }, onError: (e: Error) => setToast(e.message) });
  return <><Topbar title="Duplicate Resolution Center" />{isLoading ? <Loading /> : error ? <ErrorState message={(error as Error).message} /> : <div className="workspace-grid duplicate-layout"><Panel title="Candidate queue">{data?.items.slice(0, 20).map((group) => <button key={group.id} className={`duplicate-item ${group.id === groupId ? "active" : ""}`} onClick={() => setSelected(group.id)}><div><b>Group {group.id.slice(0, 8)}</b><span>{Math.round(group.similarity_score * 100)}% match · {group.risk_level} impact</span></div><Badge>{group.status}</Badge></button>)}</Panel><section className="card card-pad">{detail ? <><div className="section-row"><div><div className="eyebrow">Explainable entity resolution</div><h2 className="h2" style={{ fontSize: 28, marginTop: 5 }}>{Math.round(detail.similarity_score * 100)}% similarity</h2><div className="small muted">{String(detail.rationale.explanation || "Human decision required.")}</div></div><Badge>{detail.status}</Badge></div><div className="compare-grid" style={{ marginTop: 16 }}>{[detail.left, detail.right].map((product) => product && <div className="compare-side" key={product.id}><img src={product.image_url} alt="" /><h3>{product.title}</h3><p className="small muted">{product.sku || "Missing SKU"} · {product.brand}</p><div className="diff-list"><span>Price <b>${product.price}</b></span><span>Category <b>{product.category}</b></span><span>Barcode <b>{product.barcode}</b></span></div></div>)}<div className="match-meter"><div className="ring">{Math.round(detail.similarity_score * 100)}%</div><span className="small muted">Signals: SKU, title, brand, category, attributes, image abstraction</span></div></div><div className="signal-grid">{Object.entries((detail.rationale.signals || {}) as Record<string, number>).map(([key, value]) => <div key={key}><span>{key.replaceAll("_", " ")}</span><b>{Math.round(Number(value) * 100)}%</b></div>)}</div>{detail.second_review_required && <div className="callout"><ShieldCheck size={16} /><span>High-impact merge governance requires an explicit second-review confirmation. No product is silently merged.</span></div>}<div className="review-actions"><button className="btn btn-secondary" onClick={() => act.mutate({ decision: "separate" })}><XCircle size={16} /> Keep separate</button><button className="btn btn-cobalt" onClick={() => act.mutate({ decision: "merge", confirm: detail.status === "In review" })}><Merge size={16} /> {detail.status === "In review" ? "Complete second review" : "Request merge"}</button></div><div className="timeline-list">{detail.decisions.map((decision) => <div key={decision.id}><b>{decision.decision}</b><span>{decision.rationale}</span><small>{decision.decided_by}</small></div>)}</div></> : <Empty title="No duplicate group" copy="Select a candidate group to review similarity evidence." />}</section></div>}<ApiToast text={toast} /></>;
}

function Taxonomy() { const { data: categories } = useQuery({ queryKey: ["categories"], queryFn: client.categories }); const { data: attributes } = useQuery({ queryKey: ["attributes"], queryFn: client.attributes }); const { data: rules } = useQuery({ queryKey: ["rules"], queryFn: client.rules }); return <><Topbar title="Taxonomy & Attribute Governance Studio" /><div className="workspace-grid grid-3"><Panel title="Internal category tree"><div className="tree">{categories?.items.map((category) => <div key={category.id}><b>{category.path.split(" / ")[0]}</b><div className="branch">{category.name}<span className="small muted"> · v{category.version} · {category.status}</span></div></div>)}</div><p className="small muted">Impact preview API exposes products, vendors, rules, destinations, publishing risk, and approvals affected by category change.</p></Panel><Panel title="Attribute governance"><div className="attribute-governance">{attributes?.items.slice(0, 12).map((attribute) => <div key={attribute.id}><b>{attribute.name}</b><span>{attribute.category}</span><small>{attribute.data_type}{attribute.unit_type ? ` · ${attribute.unit_type}` : ""} · {attribute.required ? "required" : "optional"}</small></div>)}</div></Panel><Panel title="Validation Policy Studio"><div className="rule-list">{rules?.items.map((rule) => <div className="rule-item" key={rule.id}><div><b>{rule.name}</b><span className="small muted">{rule.field_name} · {rule.rule_type}</span></div><Badge>{rule.blocking ? "Blocking" : rule.severity}</Badge></div>)}</div><div className="callout"><ShieldCheck size={15} /><span>Policies are structured rules with scope, severity, remediation, blocking behavior, version and approval state—not an ungoverned code editor.</span></div></Panel></div></> }

function Quality() { const { data, isLoading, error } = useQuery({ queryKey: ["quality"], queryFn: client.quality }); return <><Topbar title="Validation and Data Quality Center" />{isLoading ? <Loading /> : error || !data ? <ErrorState message={(error as Error)?.message || "Unable to load quality metrics."} /> : <><div className="workspace-grid grid-kpi"><Kpi label="Catalog quality" value={`${data.overall_catalog_quality_score}%`} note="Rules-based" /><Kpi label="Completeness" value={`${data.completeness_score}%`} note="Required field coverage" /><Kpi label="Validation rate" value={`${(data.validation_failure_rate * 100).toFixed(1)}%`} note="Open findings" /><Kpi label="Duplicate risk" value={`${(data.duplicate_risk_rate * 100).toFixed(1)}%`} note="Unresolved groups" /></div><div className="workspace-grid grid-2" style={{ marginTop: 16 }}><Panel title="Data quality insight"><p className="summary-copy">{data.insight}</p><div className="callout"><AlertTriangle size={16} /><span>{data.limitations}</span></div></Panel><Panel title="Most common validation failures">{data.common_failures.map((item) => <div className="activity-row" key={item.rule}><b>{item.rule}</b><Badge>{item.count} findings</Badge></div>)}<div className="divider" /><p className="small muted">{data.blocked_products} products are currently blocked. {data.channel_readiness_records} channel-ready records are represented in the active workspace.</p></Panel></div></>}</> }

function Publish() { const queryClient = useQueryClient(); const { data: destinations } = useQuery({ queryKey: ["destinations"], queryFn: client.destinations }); const { data: jobs } = useQuery({ queryKey: ["publishJobs"], queryFn: client.publishJobs }); const { data: products } = useQuery({ queryKey: ["products", "approved"], queryFn: () => client.products("status=Approved&limit=10") }); const { data: reconciliation } = useQuery({ queryKey: ["reconciliation"], queryFn: client.reconciliation }); const [destinationId, setDestinationId] = useState(""); const [toast, setToast] = useState(""); const refresh = () => { ["publishJobs", "reconciliation", "overview", "audit"].forEach((key) => queryClient.invalidateQueries({ queryKey: [key] })); };
  const publish = useMutation({ mutationFn: (mode: string) => client.createPublish({ destination_id: destinationId || destinations?.items[0]?.id, product_ids: products?.items.slice(0, 2).map((product) => product.id), mode }), onSuccess: (data) => { setToast(`Publish workflow recorded: ${data.status}. ${data.mode === "Dry run" ? "No external system changed." : "Mock delivery verified."}`); refresh(); }, onError: (e: Error) => setToast(e.message) }); const reconcile = useMutation({ mutationFn: client.reconcile, onSuccess: (result: { issues_resolved: number }) => { setToast(`Reconciliation completed: ${result.issues_resolved} mock drift issue(s) resolved.`); refresh(); }, onError: (e: Error) => setToast(e.message) });
  return <><Topbar title="Publish center" /><div className="workspace-grid grid-2"><Panel title="Channel Readiness Center"><label>Destination<select value={destinationId} onChange={(e) => setDestinationId(e.target.value)}>{destinations?.items.map((destination) => <option key={destination.id} value={destination.id}>{destination.name} · {destination.status}</option>)}</select></label><div className="destination-list">{destinations?.items.map((destination) => <div className="destination-row" key={destination.id}><div><b>{destination.name}</b><span>{destination.type} · Mapping v{destination.mapping_version}</span></div><Badge>{destination.status}</Badge></div>)}</div><div className="callout"><ShieldCheck size={16} /><span>Only approved products with destination-ready records are eligible for a real publish mode. Local connectors remain simulated and visibly labeled.</span></div><div className="review-actions"><button className="btn btn-secondary" onClick={() => publish.mutate("Dry run")} disabled={publish.isPending}><Play size={16} /> Dry run</button><button className="btn btn-cobalt" onClick={() => publish.mutate("Publish")} disabled={publish.isPending}><Send size={16} /> Mock publish</button></div></Panel><Panel title="Publication queue" action={<button className="btn btn-secondary compact" onClick={() => reconcile.mutate()} disabled={reconcile.isPending}><RefreshCcw size={14} /> Reconcile</button>}>{jobs?.items.slice(0, 10).map((job) => <div className="publish-row" key={job.id}><div><b>{job.destination || "Destination"}</b><span>{job.item_count} records · {job.mode || "Publish"} · key {job.idempotency_key.slice(0, 16)}…</span></div><div><Badge>{job.status}</Badge>{job.status === "Failed" && <button className="icon-button" title="Retry mock publish" onClick={() => client.retryPublish(job.id).then(() => { setToast("Retry recorded and mock delivery verified."); refresh(); })}><RefreshCcw size={14} /></button>}</div></div>) || <Empty title="No publication jobs" copy="Create a dry run or mock publish batch." />}</Panel></div><Panel title="Reconciliation issues" action={<span className="small muted">Internal record vs. destination snapshot</span>}><div className="table-wrap"><table><thead><tr><th>Issue</th><th>Status</th><th>Internal snapshot</th><th>Destination snapshot</th><th>Resolution</th></tr></thead><tbody>{reconciliation?.items.map((item) => <tr key={item.id}><td>{item.issue_type}</td><td><Badge>{item.status}</Badge></td><td><code>{JSON.stringify(item.internal)}</code></td><td><code>{JSON.stringify(item.destination)}</code></td><td>{item.resolution}</td></tr>)}</tbody></table></div></Panel><ApiToast text={toast} /></> }

function Vendors() { const { data, isLoading } = useQuery({ queryKey: ["vendors"], queryFn: client.vendors }); const [selected, setSelected] = useState<string | undefined>(); const [toast, setToast] = useState(""); const vendor = selected || data?.items[0]?.id; const { data: detail } = useQuery({ queryKey: ["vendor", vendor], queryFn: () => client.vendor(vendor!), enabled: Boolean(vendor) }); const link = useMutation({ mutationFn: () => client.createIntakeLink(vendor!), onSuccess: (result: { token_preview: string }) => setToast(`Demo vendor intake link created: ${result.token_preview}`), onError: (e: Error) => setToast(e.message) }); return <><Topbar title="Vendor Quality Workspace" />{isLoading ? <Loading /> : <div className="workspace-grid vendor-layout"><Panel title="Vendor comparison"><div className="vendor-table">{data?.items.map((item) => <button key={item.id} className={`vendor-row ${item.id === vendor ? "active" : ""}`} onClick={() => setSelected(item.id)}><div><b>{item.name}</b><span>{item.catalog_volume} records · {Math.round(item.confidence * 100)}% extraction confidence</span></div><div className="quality-score">{Math.round(item.quality_score * 100)}<small>quality</small></div></button>)}</div></Panel><section className="card card-pad">{detail ? <><div className="section-row"><div><div className="eyebrow">Explainable operational score</div><h2 className="h2" style={{ fontSize: 28 }}>{detail.name}</h2><div className="small muted">Vendor template versions, source quality, validation profile, and intake history.</div></div><div className="quality-orb">{Math.round(detail.quality_score * 100)}%</div></div><div className="workspace-grid grid-3" style={{ marginTop: 15 }}><Kpi label="Files" value={detail.files} note="Source history" /><Kpi label="Validation rate" value={`${(detail.validation_failure_rate * 100).toFixed(1)}%`} note="Rules-based" /><Kpi label="Freshness" value={`${detail.source_freshness_days}d`} note="Last synthetic source" /></div><div className="divider" /><div className="section-title">Extraction template versions</div>{detail.templates.map((template) => <div className="template-row" key={template.id}><div><b>{template.name}</b><span>v{template.version} · confidence threshold {Math.round(template.confidence_threshold * 100)}%</span></div><Badge>{template.status}</Badge></div>)}<button className="btn btn-secondary" onClick={() => link.mutate()}><KeyRound size={16} /> Create demo intake link</button><div className="callout"><ShieldCheck size={16} /><span>The secure-intake link is simulated in local mode. Upload history, expiry, allowed types, template version, notification event, and audit trail are persisted; no public portal is exposed.</span></div></> : <Empty title="Select a vendor" copy="Choose a vendor to view quality evidence." />}</section></div>}<ApiToast text={toast} /></> }

function ChangeSets() { const queryClient = useQueryClient(); const { data, isLoading } = useQuery({ queryKey: ["changesets"], queryFn: client.changeSets }); const { data: products } = useQuery({ queryKey: ["products", "changeset"], queryFn: () => client.products("status=Approved&limit=3") }); const [selected, setSelected] = useState<string | undefined>(); const [toast, setToast] = useState(""); const id = selected || data?.items[0]?.id; const { data: detail } = useQuery({ queryKey: ["changeset", id], queryFn: () => client.changeSet(id!), enabled: Boolean(id) }); const create = useMutation({ mutationFn: () => client.createChangeSet({ name: "Controlled publishing draft", product_ids: products?.items.slice(0, 2).map((product) => product.id) || [], summary: "API-created governed release draft", risk_level: "Medium" }), onSuccess: (result) => { setSelected(result.id); setToast("Change set created in Draft state."); queryClient.invalidateQueries({ queryKey: ["changesets"] }); }, onError: (e: Error) => setToast(e.message) }); const submit = useMutation({ mutationFn: () => client.submitChangeSet(id!), onSuccess: () => { setToast("Change set submitted for approval."); queryClient.invalidateQueries({ queryKey: ["changeset", id] }); queryClient.invalidateQueries({ queryKey: ["changesets"] }); }, onError: (e: Error) => setToast(e.message) }); const approve = useMutation({ mutationFn: () => client.approveChangeSet(id!, "Approved"), onSuccess: () => { setToast("Approval decision recorded with role and audit history."); queryClient.invalidateQueries({ queryKey: ["changeset", id] }); queryClient.invalidateQueries({ queryKey: ["changesets"] }); }, onError: (e: Error) => setToast(e.message) }); return <><Topbar title="Change Set Detail" action={<button className="btn btn-cobalt" onClick={() => create.mutate()}><Plus size={16} /> Create change set</button>} />{isLoading ? <Loading /> : <div className="workspace-grid change-layout"><Panel title="Governed releases">{data?.items.map((item) => <button key={item.id} className={`changeset-row ${item.id === id ? "active" : ""}`} onClick={() => setSelected(item.id)}><div><b>{item.name}</b><span>{item.risk_level} risk · {item.created_by}</span></div><Badge>{item.status}</Badge></button>)}</Panel><section className="card card-pad">{detail ? <><div className="section-row"><div><div className="eyebrow">Approval gate</div><h2 className="h2" style={{ fontSize: 28 }}>{detail.name}</h2><p className="small muted">{detail.summary}</p></div><Badge>{detail.status}</Badge></div><div className="callout"><ShieldCheck size={16} /><span>Policy: {JSON.stringify(detail.approval_policy)}. Product changes are previewed before publication and rollback simulation is retained as audit evidence.</span></div><div className="diff-grid">{detail.items?.map((item) => <div key={item.id}><b>{item.entity_type} {item.product_id?.slice(0, 8)}</b><span>Before <code>{JSON.stringify(item.before)}</code></span><span>After <code>{JSON.stringify(item.after)}</code></span><Badge>{item.validation_state}</Badge></div>)}</div><div className="review-actions">{detail.status === "Draft" && <button className="btn btn-secondary" onClick={() => submit.mutate()}><Send size={16} /> Submit for approval</button>}{detail.status === "Needs review" && <button className="btn btn-cobalt" onClick={() => approve.mutate()}><Check size={16} /> Approve release</button>}<a className="btn btn-secondary" href="/workspace/publish">Open publish draft</a></div><div className="timeline-list">{detail.approvals?.map((approval) => <div key={approval.id}><b>{approval.decision}</b><span>{approval.role} · {approval.approver}</span><small>{approval.note}</small></div>)}</div></> : <Empty title="No change set selected" copy="Create a controlled product release to preview affected fields and approvals." />}</section></div>}<ApiToast text={toast} /></> }

function Lineage() { const { data: products } = useQuery({ queryKey: ["products", "lineage"], queryFn: () => client.products("limit=20") }); const [id, setId] = useState<string | undefined>(); const active = id || products?.items[0]?.id; const { data, isLoading, error } = useQuery({ queryKey: ["lineage", active], queryFn: () => client.lineage(active!), enabled: Boolean(active) }); const [toast, setToast] = useState(""); const exportPack = useMutation({ mutationFn: () => client.evidencePackage(active!), onSuccess: () => setToast("Synthetic JSON evidence package generated and audited."), onError: (e: Error) => setToast(e.message) }); return <><Topbar title="Data Lineage Explorer" />{isLoading ? <Loading /> : error ? <ErrorState message={(error as Error).message} /> : <><div className="lineage-toolbar"><label>Trace product<select value={active || ""} onChange={(e) => setId(e.target.value)}>{products?.items.map((product) => <option key={product.id} value={product.id}>{product.title}</option>)}</select></label><button className="btn btn-secondary" onClick={() => exportPack.mutate()}><Download size={16} /> Export evidence package</button></div><Panel title="Persistent lineage graph" action={<span className="small muted">Source → field → product → validation → review → publish</span>}><div className="lineage-graph">{data?.nodes.map((node) => <div className="lineage-node" key={node.id}><span>{node.type}</span><b>{node.label}</b><small>{node.id.slice(-8)}</small></div>)}</div><div className="edge-list">{data?.edges.slice(0, 18).map((edge, index) => <span key={`${edge.from}-${edge.to}-${index}`}>{edge.from.slice(-6)} <ArrowRight size={12} /> {edge.label} <ArrowRight size={12} /> {edge.to.slice(-6)}</span>)}</div></Panel><Panel title="Field-level source evidence">{data?.field_lineage.map((row, index) => <pre key={index}>{JSON.stringify(row, null, 2)}</pre>)}</Panel></>}<ApiToast text={toast} /></> }

function Reports() { const queryClient = useQueryClient(); const { data, isLoading } = useQuery({ queryKey: ["reports"], queryFn: client.reports }); const { data: alerts } = useQuery({ queryKey: ["alerts"], queryFn: client.alerts }); const [toast, setToast] = useState(""); const create = useMutation({ mutationFn: () => client.createReport({ report_type: "Vendor Quality Report", name: "Synthetic Vendor Quality Brief" }), onSuccess: (result) => { setToast(`Report generated: ${result.export_id}`); queryClient.invalidateQueries({ queryKey: ["reports"] }); }, onError: (e: Error) => setToast(e.message) }); return <><Topbar title="Reporting Center & Alerts" action={<button className="btn btn-cobalt" onClick={() => create.mutate()}><FileText size={16} /> Generate report</button>} />{isLoading ? <Loading /> : <div className="workspace-grid grid-2"><Panel title="Report library">{data?.items.map((report) => <div className="report-row" key={report.id}><div><b>{report.name}</b><span>{report.type || report.report_type} · {report.export_id}</span></div><div><Badge>{report.status}</Badge>{report.artifact_path && <a className="icon-button" title="Export PDF" href={`${process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api/v1"}/reports/${report.id}/export`} target="_blank"><Download size={14} /></a>}</div></div>)}<div className="divider" /><b className="small">Scheduled report foundation</b>{data?.scheduled.map((schedule) => <div className="small muted" key={schedule.id}>{schedule.type} · {schedule.cadence} · {schedule.delivery} · {schedule.status}</div>)}</Panel><Panel title="Operational alerts">{alerts?.items.map((alert) => <div className="alert-row" key={alert.id}><div><Badge>{alert.severity}</Badge><b>{alert.title}</b><span>{alert.message}</span></div><button className="btn btn-secondary compact" onClick={() => client.alertAction(alert.id, "acknowledge").then(() => { setToast("Alert acknowledged."); queryClient.invalidateQueries({ queryKey: ["alerts"] }); })}>Acknowledge</button></div>)}<div className="callout"><Bell size={16} /><span>In-app alerts are functional. Email, Slack-compatible webhook, and generic webhook delivery remain mock adapter boundaries in demo mode.</span></div></Panel></div>}<ApiToast text={toast} /></> }

function Intelligence() { const [question, setQuestion] = useState("Which vendors are causing the most validation failures?"); const [mode, setMode] = useState("Executive Operations Brief"); const [answer, setAnswer] = useState<Awaited<ReturnType<typeof client.assistant>> | null>(null); const query = useMutation({ mutationFn: () => client.assistant(question, mode), onSuccess: setAnswer }); return <><Topbar title="Catalog Intelligence Assistant" /><div className="workspace-grid intelligence-layout"><Panel title="Governed operations analysis"><div className="assistant-modes">{["Executive Operations Brief", "Catalog Review Mode", "Vendor Quality Mode", "Publishing Operations Mode", "Taxonomy Analysis Mode", "Data Quality Mode", "Lineage Investigation Mode"].map((item) => <button key={item} className={mode === item ? "active" : ""} onClick={() => setMode(item)}>{item}</button>)}</div><textarea className="assistant-input" value={question} onChange={(e) => setQuestion(e.target.value)} /><button className="btn btn-cobalt" onClick={() => query.mutate()} disabled={query.isPending}><WandSparkles size={16} /> {query.isPending ? "Analyzing…" : "Analyze workspace"}</button><div className="callout"><ShieldCheck size={16} /><span>The assistant only analyzes current workspace data. It does not execute product changes, publish actions, or external calls; any future draft requires explicit confirmation.</span></div></Panel><section className="card card-pad">{answer ? <><div className="eyebrow">{answer.mode}</div><h2 className="h2" style={{ fontSize: 27, marginTop: 6 }}>Executive summary</h2><p className="summary-copy">{answer.executive_summary}</p><div className="metric-inline">{Object.entries(answer.supporting_metrics).map(([key, value]) => <div key={key}><span>{key.replaceAll("_", " ")}</span><b>{value}</b></div>)}</div><div className="divider" /><b>Data sources used</b><p className="small muted">{answer.data_sources.join(" · ")}</p><b>Data-quality caveat</b><p className="small muted">{answer.data_quality_caveats}</p><b>Suggested next action</b><p className="small">{answer.suggested_next_action}</p><div className="callout"><AlertTriangle size={16} /><span>{answer.limitations}</span></div></> : <Empty title="Ask a governed catalog question" copy="Try vendor quality, validation blockers, duplicate queues, publishing status, taxonomy coverage, or source-document changes." />}</section></div></> }

function Governance() { const queryClient = useQueryClient(); const { data: settings } = useQuery({ queryKey: ["settings"], queryFn: client.settings }); const { data: keys } = useQuery({ queryKey: ["apiKeys"], queryFn: client.apiKeys }); const { data: webhooks } = useQuery({ queryKey: ["webhooks"], queryFn: client.webhooks }); const { data: roles } = useQuery({ queryKey: ["rolesUsers"], queryFn: client.rolesUsers }); const { data: audit } = useQuery({ queryKey: ["audit"], queryFn: client.audit }); const [toast, setToast] = useState(""); const newKey = useMutation({ mutationFn: () => client.createApiKey("Demo scoped ingestion key"), onSuccess: (result: { key: string }) => { setToast(`API key generated once: ${result.key.slice(0, 16)}…`); queryClient.invalidateQueries({ queryKey: ["apiKeys"] }); }, onError: (e: Error) => setToast(e.message) }); return <><Topbar title="Security & Governance Center" action={<button className="btn btn-cobalt" onClick={() => newKey.mutate()}><KeyRound size={16} /> Create API key</button>} /><div className="workspace-grid grid-3"><Panel title="Security posture"><p className="small muted">{settings?.security_wording}</p><div className="small"><b>Retention:</b> {settings?.retention_days} days</div><div className="small"><b>Legal hold:</b> {settings?.legal_hold}</div><div className="small"><b>Workspace:</b> {settings?.workspace}</div></Panel><Panel title="Users and roles">{roles?.users.map((user) => <div className="user-row" key={user.id}><span>{user.name.split(" ").map((value) => value[0]).join("")}</span><div><b>{user.name}</b><small>{user.role}</small></div></div>)}</Panel><Panel title="Scoped API keys">{keys?.items.map((key) => <div className="key-row" key={key.id}><div><b>{key.name}</b><span>{key.prefix} · {key.scopes.scopes.join(", ")}</span></div><button className="btn btn-secondary compact" disabled={Boolean(key.revoked_at)} onClick={() => client.revokeApiKey(key.id).then(() => { setToast("API key revoked."); queryClient.invalidateQueries({ queryKey: ["apiKeys"] }); })}>{key.revoked_at ? "Revoked" : "Revoke"}</button></div>)}</Panel></div><div className="workspace-grid grid-2" style={{ marginTop: 16 }}><Panel title="Webhook delivery logs">{webhooks?.items.map((hook) => <div className="webhook-row" key={hook.id}><div><b>{hook.event_type}</b><span>{hook.endpoint}</span></div><Badge>{hook.delivery_status} · {hook.status_code}</Badge></div>)}</Panel><Panel title="Audit log search view">{audit?.items.slice(0, 10).map((event) => <div className="audit-row" key={event.id}><b>{event.action}</b><span>{event.actor} · {event.entity_type} · {event.at.replace("T", " ").slice(0, 16)}</span></div>)}</Panel></div><ApiToast text={toast} /></> }

function Pipeline() { const queryClient = useQueryClient(); const { data, isLoading } = useQuery({ queryKey: ["pipeline"], queryFn: client.pipeline }); const [toast, setToast] = useState(""); return <><Topbar title="Operations Pipeline Center" />{isLoading ? <Loading /> : <><div className="workspace-grid grid-kpi"><Kpi label="Active jobs" value={data?.items.filter((item) => ["Queued", "Running", "Retrying"].includes(item.status)).length || 0} note="Durable state" /><Kpi label="Needs review" value={data?.queue_health.waiting_for_review || 0} note="Human handoff" /><Kpi label="Failed" value={data?.queue_health.failed || 0} note="Dead-letter concept" /><Kpi label="Worker mode" value={data?.queue_health.inline_mode ? "Inline" : "Worker"} note="Demo-safe" /></div><Panel title="Persistent job history" action={<span className="small muted">Retry-safe and idempotency-aware</span>}><div className="table-wrap"><table><thead><tr><th>Type</th><th>Status</th><th>Entity</th><th>Worker</th><th>Duration</th><th>Retry</th><th>Action</th></tr></thead><tbody>{data?.items.map((job) => <tr key={job.id}><td><b>{job.type}</b></td><td><Badge>{job.status}</Badge></td><td>{job.related_entity_type} · {job.related_entity_id.slice(0, 8)}</td><td>{job.worker}</td><td>{job.duration_ms || "—"} ms</td><td>{job.retry_count}</td><td><button className="btn btn-secondary compact" disabled={["Completed", "Cancelled"].includes(job.status)} onClick={() => client.retryPipeline(job.id).then((result: { status: string }) => { setToast(`Job retry state: ${result.status}`); queryClient.invalidateQueries({ queryKey: ["pipeline"] }); })}><RefreshCcw size={13} /> Retry</button></td></tr>)}</tbody></table></div></Panel></>}<ApiToast text={toast} /></> }

function Launch() { const { data, isLoading, error } = useQuery({ queryKey: ["launch"], queryFn: client.launchReadiness }); const { data: demo } = useQuery({ queryKey: ["golden-demo"], queryFn: client.goldenDemo }); const { data: contracts } = useQuery({ queryKey: ["data-contracts"], queryFn: client.dataContracts }); const { data: views } = useQuery({ queryKey: ["saved-views"], queryFn: client.savedViews }); const { data: matrix } = useQuery({ queryKey: ["permission-matrix"], queryFn: client.permissionMatrix }); return <><Topbar title="Enterprise Launch Readiness" action={<a className="btn btn-cobalt" href="/workspace/operations"><ShieldCheck size={16} /> Platform console</a>} />{isLoading ? <Loading /> : error || !data ? <ErrorState message={(error as Error)?.message || "Launch checks unavailable."} /> : <><div className="workspace-grid grid-kpi"><Kpi label="Launch readiness" value={`${data.launch_score}%`} note={data.status} /><Kpi label="Release gates" value={data.checks.length} note="API evaluated" /><Kpi label="Data contracts" value={contracts?.items.length || 0} note="Schema governed" /><Kpi label="Saved views" value={views?.items.length || 0} note="Shared operations" /></div><div className="workspace-grid grid-2" style={{ marginTop: 16 }}><Panel title="Final release gate evidence"><div className="rule-list">{data.checks.map((check) => <div className="rule-item" key={check.key}><div><b>{check.label}</b><span className="small muted">{check.severity} · {check.remediation}</span></div><Badge>{check.status}</Badge></div>)}</div><div className="callout"><AlertTriangle size={16} /><span>{data.disclaimer}</span></div></Panel><Panel title="Guided enterprise demo journey">{demo?.steps.map((step) => <a className="activity-row" key={step.step} href={step.href}><div><b>{step.step}. {step.label}</b><span>{step.entity_type} · {step.entity_id?.slice(0, 8) || "open workspace"}</span></div><ArrowRight size={16} /></a>)}<div className="callout"><ShieldCheck size={16} /><span>{demo?.operator_notes}</span></div></Panel></div><div className="workspace-grid grid-3" style={{ marginTop: 16 }}><Panel title="Data contracts">{contracts?.items.map((contract) => <div className="template-row" key={contract.id}><div><b>{contract.name}</b><span>{contract.type} · v{contract.version} · owner {contract.owner_role}</span></div><Badge>{contract.status}</Badge></div>)}</Panel><Panel title="Permission matrix">{matrix?.items.slice(0, 6).map((role) => <div className="activity-row" key={role.role}><div><b>{role.role}</b><span>{Object.values(role.permissions).filter(Boolean).length} sensitive permissions</span></div><Badge>Server enforced</Badge></div>)}</Panel><Panel title="Launch claim boundaries"><p className="small muted">Synthetic demo data is labeled, local deterministic workflows require no external keys, and mock connectors are never presented as real destination sync.</p>{Object.entries(data.claims_policy).map(([key, value]) => <div className="small" key={key}><b>{key.replaceAll("_", " ")}:</b> {value ? "enforced" : "needs review"}</div>)}</Panel></div></>}</> }

function Operations() { const { data, isLoading, error } = useQuery({ queryKey: ["operations"], queryFn: client.operations }); return <><Topbar title="Platform Operations Console" />{isLoading ? <Loading /> : error || !data ? <ErrorState message={(error as Error)?.message || "Not available."} /> : <><div className="workspace-grid grid-3">{Object.entries(data.health).map(([key, value]) => <Panel key={key} title={key.replaceAll("_", " ")}><Badge>{value}</Badge></Panel>)}</div><Panel title="Telemetry" action={<span className="small muted">Synthetic demo usage telemetry</span>}><div className="metric-inline">{Object.entries(data.telemetry).map(([key, value]) => <div key={key}><span>{key.replaceAll("_", " ")}</span><b>{typeof value === "number" && key.includes("rate") ? `${(value * 100).toFixed(1)}%` : value}</b></div>)}</div><div className="callout"><AlertTriangle size={16} /><span>{data.disclaimer}</span></div></Panel></>}</> }

export function WorkspaceView({ view }: { view: string }) { const Content = useMemo(() => ({ dashboard: Dashboard, intake: Intake, "source-intake": SourceIntake, documents: Documents, "product-master": ProductMaster, review: Review, catalog: Catalog, duplicates: Duplicates, taxonomy: Taxonomy, quality: Quality, publish: Publish, vendors: Vendors, "change-sets": ChangeSets, lineage: Lineage, reports: Reports, intelligence: Intelligence, governance: Governance, pipeline: Pipeline, operations: Operations, launch: Launch }[view] || Dashboard), [view]); return <Content />; }
